CREATE TYPE public.app_role AS ENUM ('artist','collector');
CREATE TABLE public.profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', handle text UNIQUE CHECK (handle ~ '^[a-z0-9_]+$'), city text NOT NULL DEFAULT '', mediums text[] NOT NULL DEFAULT '{}', photo text, sample boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT SELECT ON public.profiles TO anon; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO anon,authenticated,service_role;
CREATE TABLE public.rooms (id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, handle text UNIQUE NOT NULL CHECK(handle ~ '^[a-z0-9_]+$'), tagline text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', room_color text NOT NULL DEFAULT 'cream' CHECK(room_color IN ('cream','blush','butter','sage','sky','lilac','ink')), wants text[] NOT NULL DEFAULT '{}', loves text[] NOT NULL DEFAULT '{}', links jsonb NOT NULL DEFAULT '[]', faq jsonb NOT NULL DEFAULT '[]', section_order text[] NOT NULL DEFAULT ARRAY['work','shop','services','events','about','links','faq','contact'], visible_sections text[] NOT NULL DEFAULT ARRAY['work','shop','services','events','about','links','faq','contact'], published boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.rooms TO authenticated; GRANT SELECT ON public.rooms TO anon; GRANT ALL ON public.rooms TO service_role;
ALTER TABLE public.rooms ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_rooms ON public.rooms FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY own_rooms ON public.rooms FOR ALL TO authenticated USING(id=auth.uid() AND public.has_role(auth.uid(),'artist')) WITH CHECK(id=auth.uid() AND public.has_role(auth.uid(),'artist'));
CREATE POLICY public_artist_profiles ON public.profiles FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.rooms WHERE rooms.id=profiles.id AND published));
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY edit_profile ON public.profiles FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
REVOKE UPDATE ON public.profiles FROM authenticated; GRANT UPDATE(display_name,city,mediums,photo) ON public.profiles TO authenticated;
CREATE TABLE public.pieces (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, artist uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, price numeric NOT NULL DEFAULT 0 CHECK(price>=0), medium text NOT NULL DEFAULT '', size text NOT NULL DEFAULT '', collection text NOT NULL DEFAULT '', tags text[] NOT NULL DEFAULT '{}', ratio numeric NOT NULL DEFAULT 1 CHECK(ratio>0), images text[] NOT NULL DEFAULT '{}', city text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','sold','hidden')), tone text NOT NULL DEFAULT 'cream', shape integer NOT NULL DEFAULT 0, sample boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pieces TO authenticated; GRANT SELECT ON public.pieces TO anon; GRANT ALL ON public.pieces TO service_role;
ALTER TABLE public.pieces ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_pieces ON public.pieces FOR SELECT TO anon,authenticated USING(status<>'hidden' AND EXISTS(SELECT 1 FROM public.rooms WHERE id=artist AND published));
CREATE POLICY own_pieces ON public.pieces FOR ALL TO authenticated USING(artist=auth.uid() AND public.has_role(auth.uid(),'artist')) WITH CHECK(artist=auth.uid() AND public.has_role(auth.uid(),'artist'));
CREATE INDEX pieces_artist_idx ON public.pieces(artist);
CREATE TABLE public.services (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, artist uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', price_type text NOT NULL DEFAULT 'fixed' CHECK(price_type IN ('fixed','hourly','consult')), price numeric NOT NULL DEFAULT 0 CHECK(price>=0), published boolean NOT NULL DEFAULT false, sample boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.services TO authenticated; GRANT SELECT ON public.services TO anon; GRANT ALL ON public.services TO service_role;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_services ON public.services FOR SELECT TO anon,authenticated USING(published AND EXISTS(SELECT 1 FROM public.rooms WHERE id=artist AND published));
CREATE POLICY own_services ON public.services FOR ALL TO authenticated USING(artist=auth.uid() AND public.has_role(auth.uid(),'artist')) WITH CHECK(artist=auth.uid() AND public.has_role(auth.uid(),'artist'));
CREATE INDEX services_artist_idx ON public.services(artist);
CREATE TABLE public.events (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, artist uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, type text NOT NULL DEFAULT 'Class' CHECK(type IN ('Class','Opening','Market','Online session')), date date NOT NULL, start_time time NOT NULL DEFAULT '17:00', end_time time NOT NULL DEFAULT '18:00', city text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', online_link text NOT NULL DEFAULT '', price numeric NOT NULL DEFAULT 0 CHECK(price>=0), capacity integer NOT NULL DEFAULT 10 CHECK(capacity>0), bring text[] NOT NULL DEFAULT '{}', blurb text NOT NULL DEFAULT '', cover_image text, tone text NOT NULL DEFAULT 'cream', status text NOT NULL DEFAULT 'published' CHECK(status IN ('published','cancelled')), sample boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.events TO authenticated; GRANT SELECT ON public.events TO anon; GRANT ALL ON public.events TO service_role;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_events ON public.events FOR SELECT TO anon,authenticated USING(status='published' AND EXISTS(SELECT 1 FROM public.rooms WHERE id=artist AND published));
CREATE POLICY own_events ON public.events FOR ALL TO authenticated USING(artist=auth.uid() AND public.has_role(auth.uid(),'artist')) WITH CHECK(artist=auth.uid() AND public.has_role(auth.uid(),'artist'));
CREATE INDEX events_artist_idx ON public.events(artist);
CREATE TABLE public.tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event text NOT NULL REFERENCES public.events(id) ON DELETE CASCADE, collector uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','waitlist','checked in','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event,collector));
GRANT SELECT ON public.tickets TO authenticated; GRANT ALL ON public.tickets TO service_role;
ALTER TABLE public.tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_tickets ON public.tickets FOR SELECT TO authenticated USING(collector=auth.uid() OR EXISTS(SELECT 1 FROM public.events WHERE events.id=tickets.event AND events.artist=auth.uid()));
CREATE INDEX tickets_event_idx ON public.tickets(event); CREATE INDEX tickets_collector_idx ON public.tickets(collector);
CREATE POLICY attendee_profiles ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.tickets JOIN public.events ON events.id=tickets.event WHERE tickets.collector=profiles.id AND events.artist=auth.uid()));
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,user_id) VALUES(new.id,new.id); RETURN new; END $$;
CREATE TRIGGER on_gallery_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE FUNCTION public.complete_registration(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); r public.app_role; h text; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; PERFORM 1 FROM public.profiles WHERE id=u FOR UPDATE; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=u) THEN RETURN; END IF; r:=(payload->>'role')::public.app_role; h:=lower(payload->>'handle'); IF h IS NULL OR h='' THEN h:='collector_'||replace(u::text,'-',''); END IF; IF h !~ '^[a-z0-9_]+$' THEN RAISE EXCEPTION 'Invalid handle'; END IF; IF coalesce(trim(payload->>'name'),'')='' THEN RAISE EXCEPTION 'Name required'; END IF; UPDATE public.profiles SET display_name=payload->>'name',handle=h,city=coalesce(payload->>'city',''),mediums=ARRAY(SELECT jsonb_array_elements_text(coalesce(payload->'mediums','[]'))) WHERE id=u; INSERT INTO public.user_roles VALUES(u,r); IF r='artist' THEN INSERT INTO public.rooms(id,handle,bio,room_color,wants,links,published) VALUES(u,h,coalesce(payload->>'bio',''),coalesce(payload->>'room','cream'),ARRAY(SELECT jsonb_array_elements_text(coalesce(payload->'wants','[]'))),coalesce(payload->'links','[]'),true); END IF; END $$;
REVOKE ALL ON FUNCTION public.complete_registration(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.complete_registration(jsonb) TO authenticated;
CREATE FUNCTION public.event_spots(event_id text) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT greatest(0,e.capacity-(SELECT count(*)::integer FROM public.tickets t WHERE t.event=e.id AND t.status IN ('reserved','checked in'))) FROM public.events e JOIN public.rooms r ON r.id=e.artist WHERE e.id=event_id AND ((e.status='published' AND r.published) OR e.artist=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.event_spots(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.event_spots(text) TO anon,authenticated;
CREATE FUNCTION public.reserve_ticket(event_id text) RETURNS public.tickets LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.events; t public.tickets; n integer; BEGIN IF NOT public.has_role(auth.uid(),'collector') THEN RAISE EXCEPTION 'Collector account required'; END IF; SELECT * INTO e FROM public.events WHERE id=event_id FOR UPDATE; IF NOT FOUND OR e.status<>'published' OR NOT EXISTS(SELECT 1 FROM public.rooms WHERE id=e.artist AND published) THEN RAISE EXCEPTION 'Event unavailable'; END IF; IF e.price<>0 THEN RAISE EXCEPTION 'Paid tickets are coming soon'; END IF; SELECT * INTO t FROM public.tickets WHERE event=event_id AND collector=auth.uid(); IF FOUND AND t.status<>'cancelled' THEN RETURN t; END IF; SELECT count(*) INTO n FROM public.tickets WHERE event=event_id AND status IN ('reserved','checked in'); INSERT INTO public.tickets(event,collector,status) VALUES(event_id,auth.uid(),CASE WHEN n>=e.capacity THEN 'waitlist' ELSE 'reserved' END) ON CONFLICT(event,collector) DO UPDATE SET status=excluded.status RETURNING * INTO t; RETURN t; END $$;
REVOKE ALL ON FUNCTION public.reserve_ticket(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_ticket(text) TO authenticated;
CREATE FUNCTION public.check_in_ticket(ticket_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.tickets t SET status='checked in' FROM public.events e WHERE t.id=ticket_id AND e.id=t.event AND e.artist=auth.uid() AND public.has_role(auth.uid(),'artist') AND t.status='reserved'; IF NOT FOUND THEN RAISE EXCEPTION 'Ticket cannot be checked in'; END IF; END $$;
REVOKE ALL ON FUNCTION public.check_in_ticket(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.check_in_ticket(uuid) TO authenticated;
CREATE POLICY gallery_media_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id IN ('piece-images','profile-photos','event-covers'));
CREATE POLICY gallery_media_own ON storage.objects FOR ALL TO authenticated USING(bucket_id IN ('piece-images','profile-photos','event-covers') AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id IN ('piece-images','profile-photos','event-covers') AND (storage.foldername(name))[1]=auth.uid()::text AND (bucket_id='profile-photos' OR public.has_role(auth.uid(),'artist')));
