INSERT INTO public.events(id,artist,title,type,date,start_time,end_time,city,address,price,capacity,bring,blurb,tone,sample) VALUES('e1','00000000-0000-4000-8000-000000000002','Crochet for absolute beginners','Class','2026-11-24','17:00','19:30','Tegucigalpa','Casa Taller, Col. Palmira',30,10,ARRAY['Nothing! Yarn and hooks included','A snack to share, if you like'],'Learn the chain, the single stitch and how to not panic. You''ll leave with a coaster.','sage',true),('e2','00000000-0000-4000-8000-000000000001','Afternoons — opening night','Opening','2026-11-26','19:00','22:00','San Pedro Sula','Galería Barrio Río de Piedras',0,80,ARRAY['Friends','Opinions about pink'],'Twelve new paintings, one very long table and horchata.','blush',true),('e3','00000000-0000-4000-8000-000000000003','Draw-along: tiny creatures','Online session','2026-11-25','18:00','19:00','Online','',8,40,ARRAY['Paper and a pen','Camera optional'],'We draw five creatures in one hour. No talent required, only curiosity.','lilac',true),('e4','00000000-0000-4000-8000-000000000002','Sunday makers market','Market','2026-11-29','09:00','14:00','Tegucigalpa','Paseo Liquidámbar',0,200,ARRAY['A tote bag'],'Twenty artists, one sunny plaza. Come say hi.','butter',true);